// Reporting helpers implemented from public documentation and black-box probes.
import str;
when os(linux){
    extern "libc.so.6" u8* test_framework_getenv(u8* name) from "getenv";
}else{
    extern "libSystem.B.dylib" u8* test_framework_getenv(u8* name) from "getenv";
}
struct TestState{i32 passed,failed;bool json;}
TestState test_begin(){
    u8* key=str_to_cstr("MINC_AGENT");
    u8* mode=test_framework_getenv(key);
    free(key);
    return TestState{0,0,str_equal(str_from_cstr(mode),"json")};
}
void test_framework_json_string(str text){
    print("\"");
    str hex="0123456789abcdef";
    for i32 i in 0..text.len{
        u8 c=text.data[i];
        if c=='"'{print("\\\"");}
        else if c=='\\'{print("\\\\");}
        else if c=='\n'{print("\\n");}
        else if c=='\r'{print("\\r");}
        else if c=='\t'{print("\\t");}
        else if c<32{
            print("\\u00");
            write(stdout(),hex.data+(c>>4),1);
            write(stdout(),hex.data+(c&15),1);
        }else{write(stdout(),text.data+i,1);}
    }
    print("\"");
}
void test_framework_record(str name,str status,i64 ms){
    print("{\"kind\":\"test\",\"name\":");
    test_framework_json_string(name);
    print(",\"status\":");
    test_framework_json_string(status);
    print(",\"ms\":{}",ms);
}
void test_framework_output(str output){
    if output.len>0{
        print(",\"output\":");
        test_framework_json_string(output);
    }
    print("}\n");
}
void test_report(TestState* state,str name,bool passed,i64 ms,str output){
    if passed{state.passed++;}else{state.failed++;}
    if state.json{
        test_framework_record(name,passed?"pass":"fail",ms);
        test_framework_output(output);
    }else{
        print("  {}  {}\n",passed?"PASS":"FAIL",name);
        if !passed&&output.len>0{print("{}",output);}
    }
}
void test_report_fail(TestState* state,str name,i64 ms,i32 code,bool timeout,str output){
    state.failed++;
    if state.json{
        test_framework_record(name,"fail",ms);
        if timeout{print(",\"reason\":\"timeout\"");}
        else{print(",\"exit\":{}",code);}
        test_framework_output(output);
    }else{
        if timeout{print("  FAIL  {} (timeout)\n",name);}
        else{print("  FAIL  {} (exit {})\n",name,code);}
        if output.len>0{print("{}",output);}
    }
}
i32 test_finish(TestState* state){
    if state.json{
        print("{\"kind\":\"results\",\"passed\":{},\"failed\":{},\"unchanged\":0}\n",state.passed,state.failed);
    }else{print("{} passed, {} failed\n",state.passed,state.failed);}
    return state.failed>0?1:0;
}

