    TestState state=test_begin();
    str_buf path;str_buf_init(&path);
    while true{
        i32 byte=test_framework_fgetc(files);
        if byte<0{break;}
        if byte!=0{u8 value=cast(u8,byte);str_buf_add(&path,str{&value,1});continue;}
        str source=str_buf_to_str(&path);
        i32 base=0;
        for i32 j in 0..source.len{if source.data[j]=='/'{base=j+1;}}
        str name=str_slice(source,base,source.len-3);
        if str_contains(name,filter){
            using string binary=format("build/test/{}",name);
            using string quoted_source=test_framework_quote(source);
            using string quoted_binary=test_framework_quote(binary);
            using string compile=format("{} build {} -o {} >{} 2>&1",quoted_compiler,quoted_source,quoted_binary,quoted_compile_log);
